var ITEMS=[[".","Any single character except newline."], ["^","Start of string or line."], ["$","End of string or line."], ["*","Zero or more of the previous."], ["+","One or more of the previous."], ["?","Zero or one of the previous."], ["{n}","Exactly n of the previous."], ["{n,}","n or more of the previous."], ["{n,m}","Between n and m of the previous."], ["[...]","Any one character in the set."], ["[^...]","Any one character NOT in the set."], ["\\d","Any digit, 0-9."], ["\\D","Any non-digit."], ["\\w","Word character: letters, digits, underscore."], ["\\W","Non-word character."], ["\\s","Whitespace."], ["\\S","Non-whitespace."], ["\\b","Word boundary."], ["\\B","Not a word boundary."], ["\\A","Absolute start of string."], ["\\Z","Absolute end of string."], ["|","Alternation: this or that."], ["(...)","Capturing group."], ["(?:...)","Non-capturing group."], ["(?=...)","Positive lookahead."], ["(?!...)","Negative lookahead."], ["\\1","Backreference to group 1."], ["(?i)","Case-insensitive flag."], ["\\.","Literal dot."], ["\\\\","Literal backslash."], ["\\+","Literal plus."], ["\\*","Literal star."], ["\\?","Literal question mark."], ["\\$","Literal dollar."], ["\\^","Literal caret."], ["\\|","Literal pipe."], ["\\(","Literal open paren."], ["\\)","Literal close paren."], ["\\[","Literal open bracket."], ["\\{","Literal open brace."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
